import { randomUUID } from 'node:crypto';
import { setTimeout as delay } from 'node:timers/promises';
import type { Collection, Db } from 'mongodb';
import { withAbort } from '../adminPinnedHttps';
import {
    METADATA_LOOKUP_RATES, METADATA_LOOKUP_RETRY, MetadataLookupSourceError,
    type LookupGateMode, type LookupSourceRate, type MetadataLookupSource
} from './lookupContract';

/**
 * Per-source request spacing and concurrency for metadata lookup. The MongoDB gate is the one
 * deployment-wide bound the rules require: every application instance shares one `_id`-keyed
 * document per source, decided on the database clock. Wait mode sleeps until a slot opens, for at
 * most `METADATA_LOOKUP_RETRY.maximumWaitMs`. Busy mode sleeps out only the caller's own spacing, so
 * one lookup's consecutive requests are paced rather than refused, and reports `busy` when another
 * request holds the source, a backoff pushed it back further than one interval, or another caller
 * took the slot it waited for. A lease that is never released (crash, unknown outcome) expires.
 */
export interface LookupGateLease {
    /** Idempotent, never throws and waits at most one second; `backoffMs` pushes the source's next start (Retry-After). */
    release(outcome?: { backoffMs?: number }): Promise<void>;
}
export interface MetadataLookupRateGate {
    acquire(source: MetadataLookupSource, mode: LookupGateMode, signal: AbortSignal): Promise<LookupGateLease>;
}

export const adminMetadataLookupGateCollection = 'adminMetadataLookupGates';
/** One document per source; it holds no account data and needs no secondary index. */
type GateDocument = { _id: MetadataLookupSource; nextAt: Date; leases: { id: string; expiresAt: Date }[]; observedAt: Date };
type Sleep = (ms: number, signal: AbortSignal) => Promise<void>;
type RateOverrides = Partial<Record<MetadataLookupSource, LookupSourceRate>>;
/** What a refused acquisition saw, in milliseconds on the gate's own clock. */
type Refusal = { nextAt: number; observed: number; leases: number; earliestExpiry: number };

/** Client-side bound of one gate command; `maxTimeMS` alone does not cover server selection or a dead socket. */
const gateCommandMs = 2000;
const releaseWaitMs = 1000;

const clamp = (value: number, minimum: number, maximum: number) => Math.min(maximum, Math.max(minimum, Number.isFinite(value) ? value : maximum));
const defaultSleep: Sleep = (ms, signal) => delay(ms, undefined, { signal }).then(() => undefined);
const rateFor = (rates: RateOverrides | undefined, source: MetadataLookupSource) => rates?.[source] ?? METADATA_LOOKUP_RATES[source];

/** Waits for `work` at most `ms`; the work keeps running on its own and its failure is ignored. */
const settleWithin = async (work: Promise<unknown>, ms: number) => {
    let timer: NodeJS.Timeout | undefined;
    const bound = new Promise<void>(resolve => { timer = setTimeout(resolve, ms); timer.unref(); });
    try { await Promise.race([work.then(() => undefined, () => undefined), bound]); }
    finally { clearTimeout(timer); }
};

/**
 * The next step after a refusal. Wait mode polls after the remaining spacing or, while every lease
 * is held, after about one interval (never past the earliest expiry). Busy mode sleeps only while
 * no lease blocks it, the spacing is at most one interval and the next start is still the one it
 * waited for; `waitedFor` is that next start, or null before the first sleep.
 */
const afterRefusal = (mode: LookupGateMode, rate: LookupSourceRate, refusal: Refusal, waitedFor: number | null):
    { busyAfterMs: number } | { sleepMs: number } => {
    const spacingMs = Math.max(0, refusal.nextAt - refusal.observed);
    const full = refusal.leases >= rate.concurrency;
    const untilExpiryMs = full ? Math.max(0, refusal.earliestExpiry - refusal.observed) : 0;
    if (mode === 'busy' && (full || spacingMs > rate.intervalMs || (waitedFor !== null && refusal.nextAt !== waitedFor))) {
        return { busyAfterMs: clamp(Math.max(spacingMs, untilExpiryMs), 50, 60_000) };
    }
    return { sleepMs: clamp(Math.max(spacingMs, full ? Math.min(untilExpiryMs, Math.max(rate.intervalMs, 250)) : 0), 50, 2000) };
};

/** Sleeps before the next attempt; an abort while sleeping is `cancelled`. */
const waitOrCancel = async (source: MetadataLookupSource, ms: number, signal: AbortSignal, sleep: Sleep) => {
    if (signal.aborted) throw new MetadataLookupSourceError(source, 'cancelled');
    try { await sleep(ms, signal); }
    catch { throw new MetadataLookupSourceError(source, 'cancelled'); }
    if (signal.aborted) throw new MetadataLookupSourceError(source, 'cancelled');
};

/** Applies `afterRefusal`: throws `busy`, or `unavailable` once the total wait bound would be passed, or sleeps. */
const handleRefusal = async (source: MetadataLookupSource, mode: LookupGateMode, rate: LookupSourceRate, refusal: Refusal,
    waitedFor: number | null, elapsedMs: number, signal: AbortSignal, sleep: Sleep) => {
    const step = afterRefusal(mode, rate, refusal, waitedFor);
    if ('busyAfterMs' in step) throw new MetadataLookupSourceError(source, 'busy', step.busyAfterMs);
    if (elapsedMs + step.sleepMs > METADATA_LOOKUP_RETRY.maximumWaitMs) throw new MetadataLookupSourceError(source, 'unavailable');
    await waitOrCancel(source, step.sleepMs, signal, sleep);
    return refusal.nextAt;
};

/** Deployment-wide gate on the shared database. Its documents are written only outside transactions. */
export const createMongoLookupRateGate = (db: Db, options: { rates?: RateOverrides; sleep?: Sleep } = {}): MetadataLookupRateGate => {
    const sleep = options.sleep ?? defaultSleep;
    const gates = (): Collection<GateDocument> => db.collection<GateDocument>(adminMetadataLookupGateCollection);

    /** One atomic step on the server clock: drop expired leases, then grant when spacing and concurrency allow. */
    const attempt = async (source: MetadataLookupSource, id: string, rate: LookupSourceRate) => {
        const pipeline = [
            { $set: {
                leases: { $filter: { input: { $ifNull: ['$leases', []] }, as: 'lease', cond: { $gt: ['$$lease.expiresAt', '$$NOW'] } } },
                nextAt: { $ifNull: ['$nextAt', new Date(0)] }, observedAt: '$$NOW'
            } },
            { $set: { grant: { $and: [{ $lte: ['$nextAt', '$$NOW'] }, { $lt: [{ $size: '$leases' }, rate.concurrency] }] } } },
            { $set: {
                leases: { $cond: ['$grant', { $concatArrays: ['$leases', [{ id, expiresAt: { $add: ['$$NOW', rate.leaseMs] } }]] }, '$leases'] },
                nextAt: { $cond: ['$grant', { $add: ['$$NOW', rate.intervalMs] }, '$nextAt'] }
            } },
            { $unset: 'grant' }
        ];
        for (let race = 0; ; race++) {
            try {
                const result = await gates().findOneAndUpdate({ _id: source }, pipeline, { upsert: true, returnDocument: 'after', maxTimeMS: 1000 });
                return result.value;
            } catch (error) {
                // Concurrent first-time upserts can collide on `_id`; the document exists after one retry.
                if ((error as { code?: number }).code === 11000 && race === 0) continue;
                throw error;
            }
        }
    };

    /** Removes only the lease with this id; it never shortens the next start. */
    const release = async (source: MetadataLookupSource, id: string, backoffMs: number) => {
        await gates().updateOne({ _id: source }, [{ $set: {
            leases: { $filter: { input: { $ifNull: ['$leases', []] }, as: 'lease',
                cond: { $and: [{ $ne: ['$$lease.id', id] }, { $gt: ['$$lease.expiresAt', '$$NOW'] }] } } },
            nextAt: { $max: [{ $ifNull: ['$nextAt', new Date(0)] }, { $add: ['$$NOW', backoffMs] }] }
        } }], { maxTimeMS: 1000 });
    };

    return {
        async acquire(source, mode, signal) {
            const rate = rateFor(options.rates, source);
            const startedAt = Date.now();
            let waitedFor: number | null = null;
            for (;;) {
                if (signal.aborted) throw new MetadataLookupSourceError(source, 'cancelled');
                const id = randomUUID();
                const pending = attempt(source, id, rate);
                const bound = AbortSignal.any([signal, AbortSignal.timeout(gateCommandMs)]);
                let document: GateDocument | null;
                try {
                    document = await withAbort(pending, bound, () => new MetadataLookupSourceError(source, signal.aborted ? 'cancelled' : 'unavailable'));
                } catch (error) {
                    // Unknown outcome: the update may have been applied with its reply lost, or may still be in
                    // flight. `release` matches only this attempt's id, so it frees an orphan grant and is
                    // otherwise a no-op. After an abort or timeout it runs once the command settles.
                    const cleanup = pending.then(() => undefined, () => undefined).then(() => release(source, id, 0));
                    cleanup.catch(() => undefined);
                    if (error instanceof MetadataLookupSourceError) throw error;
                    await settleWithin(cleanup, releaseWaitMs);
                    throw new MetadataLookupSourceError(source, 'unavailable');
                }
                if (!document || !Array.isArray(document.leases) || !(document.nextAt instanceof Date) || !(document.observedAt instanceof Date)) {
                    await settleWithin(release(source, id, 0), releaseWaitMs);
                    throw new MetadataLookupSourceError(source, 'unavailable');
                }
                if (document.leases.some(lease => lease?.id === id)) {
                    let released = false;
                    const lease: LookupGateLease = {
                        async release(outcome) {
                            if (released) return;
                            released = true;
                            const backoffMs = clamp(Math.round(outcome?.backoffMs ?? 0), 0, 60_000);
                            // A failed or slow release leaves the lease to expire after leaseMs; no answer waits for it.
                            await settleWithin(release(source, id, backoffMs), releaseWaitMs);
                        }
                    };
                    if (signal.aborted) { await lease.release(); throw new MetadataLookupSourceError(source, 'cancelled'); }
                    return lease;
                }
                const observed = document.observedAt.getTime();
                waitedFor = await handleRefusal(source, mode, rate, {
                    nextAt: document.nextAt.getTime(), observed, leases: document.leases.length,
                    earliestExpiry: Math.min(...document.leases.map(lease => lease?.expiresAt instanceof Date ? lease.expiresAt.getTime() : observed))
                }, waitedFor, Date.now() - startedAt, signal, sleep);
            }
        }
    };
};

/**
 * Process-local gate for the fixture recorder and unit tests only. It is never used in production,
 * because it does not bound other application instances.
 */
export const createProcessLookupRateGate = (options: { rates?: RateOverrides; now?: () => number; sleep?: Sleep } = {}): MetadataLookupRateGate => {
    const now = options.now ?? Date.now;
    const sleep = options.sleep ?? defaultSleep;
    const state = new Map<MetadataLookupSource, { nextAt: number; leases: Map<string, number> }>();
    return {
        async acquire(source, mode, signal) {
            const rate = rateFor(options.rates, source);
            const startedAt = now();
            let waitedFor: number | null = null;
            for (;;) {
                if (signal.aborted) throw new MetadataLookupSourceError(source, 'cancelled');
                const current = state.get(source) ?? { nextAt: 0, leases: new Map<string, number>() };
                state.set(source, current);
                const time = now();
                for (const [id, expiresAt] of current.leases) if (expiresAt <= time) current.leases.delete(id);
                if (current.nextAt <= time && current.leases.size < rate.concurrency) {
                    const id = randomUUID();
                    current.leases.set(id, time + rate.leaseMs);
                    current.nextAt = time + rate.intervalMs;
                    let released = false;
                    return {
                        async release(outcome) {
                            if (released) return;
                            released = true;
                            current.leases.delete(id);
                            current.nextAt = Math.max(current.nextAt, now() + clamp(Math.round(outcome?.backoffMs ?? 0), 0, 60_000));
                        }
                    };
                }
                waitedFor = await handleRefusal(source, mode, rate, {
                    nextAt: current.nextAt, observed: time, leases: current.leases.size, earliestExpiry: Math.min(...current.leases.values())
                }, waitedFor, time - startedAt, signal, sleep);
            }
        }
    };
};
